<h1><?= te('Client access') ?></h1>
<p class="sub"><?= te('Client accounts see only authorized projects and business reports. Employee documents and payroll remain private.') ?></p>
<div class="grid g2">
<form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="create"><h2><?= te('Create client account') ?></h2><label><?= te('Name') ?></label><input name="name" required maxlength="190"><label><?= te('Email') ?></label><input name="email" type="email" required maxlength="190"><label><?= te('Client') ?></label><select name="client_id" required><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Create account') ?></button></form>
<form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="grant"><h2><?= te('Grant client access') ?></h2><label><?= te('Account') ?></label><select name="user_id" required><?php foreach($accounts as $account): ?><option value="<?= (int)$account['id'] ?>"><?= e($account['name'].' · '.$account['email']) ?></option><?php endforeach; ?></select><label><?= te('Client') ?></label><select name="client_id" required><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select><button class="btn"><?= te('Grant access') ?></button></form>
</div>
<div class="card scroll"><table><thead><tr><th><?= te('Account') ?></th><th><?= te('Client') ?></th><th><?= te('Actions') ?></th></tr></thead><tbody><?php foreach($grants as $grant): ?><tr><td><?= e($grant['name'].' · '.$grant['email']) ?></td><td><?= e($grant['client_name']) ?></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="revoke"><input type="hidden" name="user_id" value="<?= (int)$grant['user_id'] ?>"><input type="hidden" name="client_id" value="<?= (int)$grant['client_id'] ?>"><button class="btn ghost sm"><?= te('Revoke access') ?></button></form></td></tr><?php endforeach; ?></tbody></table></div>
